using UnityEngine;
using UnityEngine.TextCore.Text;
using UnityEngine.UIElements;

namespace Myrtana.Unity.Ui.Skin
{
    /// <summary>
    /// Entry point of the imported G3 skin: generated by <c>G3/GUI/Import</c> into
    /// <c>Assets/G3Imported/Gui/Resources/G3Gui/G3Skin.asset</c> (game-derived, git-ignored) and loaded by
    /// <see cref="G3Skin.Load"/>. Images are in one <see cref="G3ImageLibrary"/> per igl group next to it
    /// (<c>Resources/G3Gui/Images/&lt;group&gt;</c>), loaded only when a screen needs them.
    /// </summary>
    public sealed class G3SkinAssets : ScriptableObject
    {
        public const string ResourcePath = "G3Gui/G3Skin";
        public const string ImageLibraryFolder = "G3Gui/Images/";

        [Tooltip("G3GuiData.json: theme, image index and the 62 screen layouts (Myrtana.Ui.Skin.GuiSkinData).")]
        public UnityEngine.TextAsset data;

        [Tooltip("Generated G3Theme.uss: widget part classes with per-state tints.")]
        public StyleSheet theme;

        [Tooltip("Gothic3.ttf from the game folder (null when the game has none).")]
        public Font font;

        [Tooltip("Dynamic SDF font asset of the imported Gothic3.ttf (its broken Cyrillic is removed; Russian uses the fallbacks).")]
        public FontAsset fontAsset;
    }
}
